package com.project.web.controller.system;
import java.util.*;import javax.servlet.http.HttpSession;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.apache.shiro.authz.annotation.RequiresPermissions;import org.springframework.jdbc.core.JdbcTemplate;import com.project.common.utils.ShiroUtils;import com.project.system.service.*;
@Controller @RequestMapping("/system/merchantApi") @RequiresPermissions("campus:api:manage") public class MerchantApiAdminController{
 @Autowired private MerchantApiService service;@Autowired private MerchantGatewayController gateway;@Autowired private JdbcTemplate db;
 private void token(HttpSession session,String token){if(token==null||!token.equals(session.getAttribute("apiToken")))throw new IllegalArgumentException("页面已过期，请刷新");}
 @GetMapping public String page(long merchant,Model model,HttpSession session){service.ensure(merchant);if(session.getAttribute("apiToken")==null)session.setAttribute("apiToken",UUID.randomUUID().toString());model.addAttribute("merchant",merchant);model.addAttribute("token",session.getAttribute("apiToken"));return "merchant-api";}
 @GetMapping("/data") @ResponseBody public Object data(long merchant,@RequestParam(defaultValue="1")int page){return service.adminData(merchant,page);}
 @PostMapping("/config") @ResponseBody public Object config(long merchant,boolean enabled,boolean recharge,boolean pay,String callback,String token,HttpSession session){token(session,token);service.configure(merchant,enabled,recharge,pay,callback,ShiroUtils.getUserId());return Collections.singletonMap("ok",true);}
 @PostMapping("/rotate") @ResponseBody public Object rotate(long merchant,String token,HttpSession session){token(session,token);return Collections.singletonMap("secret",service.rotate(merchant,ShiroUtils.getUserId()));}
 @PostMapping("/demo") @ResponseBody public Object demo(long merchant,String action,String body,String token,HttpSession session){token(session,token);service.ensure(merchant);Map<String,Object> c=db.queryForMap("select * from campus_api_credential where merchant_id=?",merchant);String time=String.valueOf(java.time.Instant.now().getEpochSecond()),nonce=UUID.randomUUID().toString(),path="/api/v1/merchant/"+action,signature=ApiSecurity.sign((String)c.get("secret"),time,nonce,path,body);org.springframework.http.ResponseEntity<String> response=gateway.dispatch(action,body,(String)c.get("public_id"),time,nonce,signature);Map<String,Object> out=new LinkedHashMap<>();out.put("path",path);out.put("requestHeaders",new LinkedHashMap<String,String>(){{put("X-Merchant-Id",String.valueOf(c.get("public_id")));put("X-Timestamp",time);put("X-Nonce",nonce);put("X-Signature",signature);}});out.put("httpStatus",response.getStatusCodeValue());out.put("response",response.getBody());return out;}
 @ExceptionHandler(IllegalArgumentException.class) @ResponseBody @ResponseStatus(org.springframework.http.HttpStatus.BAD_REQUEST) public Object error(IllegalArgumentException e){return Collections.singletonMap("error",e.getMessage());}
}
